-- Existing legacy column definitions only; synthetic rows are created by the integration test.
CREATE TABLE public.sauna_types (
    id text NOT NULL,
    name text NOT NULL,
    description text NOT NULL,
    placement text NOT NULL,
    reservation_fee_cents integer NOT NULL,
    stripe_payment_link text NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    location text NOT NULL,
    style text NOT NULL,
    model_key text NOT NULL,
    CONSTRAINT sauna_types_location_check CHECK ((location = ANY (ARRAY['indoor'::text, 'outdoor'::text]))),
    CONSTRAINT sauna_types_model_key_check CHECK ((model_key = ANY (ARRAY['standard'::text, 'original'::text]))),
    CONSTRAINT sauna_types_placement_check CHECK ((placement = ANY (ARRAY['indoor'::text, 'outdoor'::text, 'either'::text]))),
    CONSTRAINT sauna_types_style_check CHECK ((style = ANY (ARRAY['traditional'::text, 'infrared'::text])))
);

CREATE TABLE public.reservations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    sauna_type_id text NOT NULL,
    first_name text NOT NULL,
    last_name text NOT NULL,
    email text NOT NULL,
    phone text,
    install_address text,
    placement_choice text,
    access_notes text,
    min_commitment_months integer,
    preferred_install_at timestamp with time zone NOT NULL,
    reservation_status text DEFAULT 'Pending Payment'::text NOT NULL,
    payment_status text DEFAULT 'Pending'::text NOT NULL,
    contract_status text DEFAULT 'Not Sent'::text NOT NULL,
    id_status text DEFAULT 'Not Uploaded'::text NOT NULL,
    consult_status text DEFAULT 'Not Scheduled'::text NOT NULL,
    admin_notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    sauna_inventory_id uuid,
    secure_token text DEFAULT encode(extensions.gen_random_bytes(32), 'hex'::text) NOT NULL,
    city text,
    reservation_source text DEFAULT 'Unknown'::text NOT NULL,
    hold_created_at timestamp with time zone,
    hold_deadline timestamp with time zone,
    stripe_payment_id text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    payment_completed_at timestamp with time zone,
    stripe_checkout_session_id text,
    stripe_payment_intent_id text,
    video_consult_booking_id text,
    video_consult_scheduled_at timestamp with time zone,
    installation_booking_id text,
    installation_scheduled_at timestamp with time zone,
    installation_status text DEFAULT 'Not Scheduled'::text NOT NULL,
    stripe_customer_id text,
    stripe_customer_linkage_missing boolean DEFAULT false NOT NULL,
    ach_status text DEFAULT 'Not Connected'::text NOT NULL,
    ach_connected_at timestamp with time zone,
    stripe_ach_setup_intent_id text,
    stripe_ach_payment_method_id text,
    ach_bank_name text,
    ach_bank_last4 text,
    ach_last_error text,
    default_payment_method_status text,
    default_payment_method_updated_at timestamp with time zone,
    magic_link_opened_at timestamp with time zone,
    custom_commitment_months integer,
    custom_monthly_price integer,
    default_sauna_type text,
    custom_security_deposit integer,
    allowed_commitment_months integer[],
    custom_install_fee integer,
    custom_pricing_options jsonb,
    custom_contract_terms jsonb,
    custom_delivery_fee integer,
    custom_stair_elevator_charge integer,
    crm_monthly_price integer,
    CONSTRAINT reservations_ach_status_check CHECK ((ach_status = ANY (ARRAY['Not Connected'::text, 'In Progress'::text, 'Connected'::text, 'Failed'::text]))),
    CONSTRAINT reservations_custom_delivery_fee_nonnegative CHECK (((custom_delivery_fee IS NULL) OR (custom_delivery_fee >= 0))),
    CONSTRAINT reservations_custom_stair_charge_nonnegative CHECK (((custom_stair_elevator_charge IS NULL) OR (custom_stair_elevator_charge >= 0))),
    CONSTRAINT reservations_min_commitment_months_check CHECK ((min_commitment_months = ANY (ARRAY[1, 3, 6, 12])))
);

CREATE TABLE public.sauna_inventory (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    sauna_type_id text NOT NULL,
    model text,
    indoor_outdoor_eligibility text DEFAULT 'either'::text NOT NULL,
    status text DEFAULT 'Available'::text NOT NULL,
    current_customer text,
    install_date date,
    minimum_term_ends date,
    notice_received_date date,
    available_date date,
    incoming_eta date,
    admin_notes text,
    reservation_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    unit_code text,
    future_customer text,
    current_customer_id uuid,
    future_customer_id uuid,
    locations text[] NOT NULL,
    style text NOT NULL,
    model_key text NOT NULL,
    CONSTRAINT sauna_inventory_indoor_outdoor_eligibility_check CHECK ((indoor_outdoor_eligibility = ANY (ARRAY['indoor'::text, 'outdoor'::text, 'either'::text]))),
    CONSTRAINT sauna_inventory_locations_check CHECK (((array_length(locations, 1) >= 1) AND (locations <@ ARRAY['indoor'::text, 'outdoor'::text]))),
    CONSTRAINT sauna_inventory_model_check CHECK (((model IS NULL) OR (model = ANY (ARRAY['Standard'::text, 'Original Collection'::text, 'v1 — Fir/Cedar'::text, 'v2 — Cedar'::text])))),
    CONSTRAINT sauna_inventory_model_key_check CHECK ((model_key = ANY (ARRAY['standard'::text, 'original'::text, 'v1_fir_cedar'::text, 'v2_cedar'::text]))),
    CONSTRAINT sauna_inventory_status_check CHECK ((status = ANY (ARRAY['Available'::text, 'Reservation Hold'::text, 'Reservation Confirmed'::text, 'Installed'::text, 'Returning'::text, 'Maintenance'::text, 'Incoming'::text, 'Transfer Planned'::text, 'Sold'::text, 'Pre-sold'::text]))),
    CONSTRAINT sauna_inventory_style_check CHECK ((style = ANY (ARRAY['traditional'::text, 'infrared'::text])))
);

CREATE TABLE public.contracts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    reservation_id uuid NOT NULL,
    agreement_version_id uuid NOT NULL,
    status text DEFAULT 'Not Started'::text NOT NULL,
    customer_legal_name text NOT NULL,
    phone text,
    email text NOT NULL,
    installation_address text,
    sauna_type text NOT NULL,
    placement text NOT NULL,
    commitment_months integer NOT NULL,
    monthly_price integer NOT NULL,
    delivery_fee integer NOT NULL,
    security_deposit integer NOT NULL,
    insurance_selected boolean DEFAULT false NOT NULL,
    insurance_monthly_price integer DEFAULT 0 NOT NULL,
    second_heater_selected boolean DEFAULT false NOT NULL,
    second_heater_monthly_price integer DEFAULT 0 NOT NULL,
    stair_elevator_charge integer,
    preferred_installation_date date,
    rental_summary_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    pricing_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    admin_overrides jsonb DEFAULT '{}'::jsonb NOT NULL,
    generated_at timestamp with time zone,
    signed_at timestamp with time zone,
    voided_at timestamp with time zone,
    void_reason text,
    replaces_contract_id uuid,
    signed_pdf_storage_path text,
    signed_pdf_hash text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.reservation_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    reservation_id uuid NOT NULL,
    event_type text NOT NULL,
    message text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.waitlist_entries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    first_name text NOT NULL,
    last_name text NOT NULL,
    email text NOT NULL,
    phone text,
    city text,
    sauna_type_id text NOT NULL,
    preferred_install_date date,
    reservation_source text DEFAULT 'Unknown'::text NOT NULL,
    status text DEFAULT 'Open'::text NOT NULL,
    admin_notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    reservation_id uuid,
    reason text
);
